<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne; use App\Enums\JobStatus;
class Job extends Model {use HasFactory; protected $guarded=[]; protected $casts=['checked_in_at'=>'datetime','completed_at'=>'datetime','status'=>JobStatus::class]; protected static function boot(){parent::boot();static::creating(function($job){if(empty($job->job_number)){$job->job_number='JOB-'.date('Y').'-'.str_pad(static::whereYear('created_at',date('Y'))->count()+1,6,'0',STR_PAD_LEFT);}});} public function customer(): BelongsTo {return $this->belongsTo(Customer::class);} public function vehicle(): BelongsTo {return $this->belongsTo(Vehicle::class);} public function business(): BelongsTo {return $this->belongsTo(Business::class);} public function branch(): BelongsTo {return $this->belongsTo(Branch::class);} public function appointment(): BelongsTo {return $this->belongsTo(Appointment::class);} public function technician(): BelongsTo {return $this->belongsTo(User::class,'technician_id');} public function services(): HasMany {return $this->hasMany(JobService::class);} public function parts(): HasMany {return $this->hasMany(JobPart::class);} public function inspection(): HasOne {return $this->hasOne(Inspection::class);} public function invoice(): HasOne {return $this->hasOne(Invoice::class);} public function qualityCheck(): HasOne {return $this->hasOne(QualityCheck::class);} public function statusHistory(): HasMany {return $this->hasMany(JobStatusHistory::class);} public function additionalWorkRequests(): HasMany {return $this->hasMany(AdditionalWorkRequest::class);} public function serviceBayAssignments(): HasMany {return $this->hasMany(ServiceBayAssignment::class);} public function workTimeLogs(): HasMany {return $this->hasMany(WorkTimeLog::class);} public function customerSuppliedParts(): HasMany {return $this->hasMany(CustomerSuppliedPart::class);} public function emergencyPurchases(): HasMany {return $this->hasMany(EmergencyPurchase::class);} public function communications(): HasMany {return $this->hasMany(Communication::class);} public function transitionTo(JobStatus $newStatus,?User $user=null,?string $reason=null): bool{if(!$this->status->canTransitionTo($newStatus)){throw new \InvalidArgumentException("Cannot transition from {$this->status->value} to {$newStatus->value}");}$oldStatus=$this->status;$this->status=$newStatus;$this->save();JobStatusHistory::create(['job_id'=>$this->id,'from_status'=>$oldStatus?->value,'to_status'=>$newStatus->value,'changed_by'=>$user?->id,'reason'=>$reason]);return true;} public function canBeDelivered(): bool{return $this->status===JobStatus::PAID&&$this->invoice?->balance<=0;} public function isAwaitingApproval(): bool{return $this->status===JobStatus::CUSTOMER_APPROVAL_PENDING||$this->services()->where('approval_status','pending')->exists();} public function getEstimatedTotalAttribute(): float{$servicesTotal=$this->services()->where('approval_status','!=','rejected')->sum('unit_price');$partsTotal=$this->parts()->where('approved',true)->sum(\DB::raw('quantity * unit_price'));return $servicesTotal+$partsTotal;} public function jobServices(){return $this->hasMany(JobService::class);
}}
